public class Main {
    static int[] getModifiedArray(int length, int[][] updates) {
        int[] diff = new int[length + 1];
        for (int[] u : updates) {
            diff[u[0]] += u[2];                  // increment begins here
            diff[u[1] + 1] -= u[2];              // and is cancelled right after the range
        }
        int[] result = new int[length];
        int running = 0;
        for (int i = 0; i < length; i++) {
            running += diff[i];                   // one sweep reconstructs the true value
            result[i] = running;
        }
        return result;
    }
}

